Query to get the balance history

{noformat}SELECT date(bbd.created) as date_id, bbd.transaction_type, bbd.amount, sum(bbd.amount) over(partition by bbd.entity_id, bbd.currency order by bbd.created, bbd.transaction_type rows between unbounded preceding and current row) as current_balance, bbd.entity_id
FROM ng_public.etl_billing_balance_driver bbd 
left join ng_public.invoicing_client ic on ic.id = bbd.entity_id
WHERE bbd.entity_type = 'driver_fleet' and ic.external_id = ${FLEET ID}
order by bbd.created, bbd.transaction_type{noformat}

